// Shared Playwright config (owned by packages/replay). Used by:
//   tests/e2e/*.spec.ts          baseline flows (CareRx demo app)
//   tests/regressions/*.spec.ts  issue-<iid>.spec.ts generated by packages/replay/bin/to-spec.js
// Point it at any SplitPal revision with BASE_URL (default http://localhost:8080).
import { defineConfig, devices } from '@playwright/test';

const viewport = { width: 390, height: 844 };

export default defineConfig({
  testDir: 'tests',
  testIgnore: ['unit/**'],
  fullyParallel: false,
  forbidOnly: !!process.env.CI,
  retries: 0, // regression specs must fail deterministically before the fix
  timeout: 30_000,
  expect: { timeout: 5_000 },
  reporter: [['line'], ['junit', { outputFile: 'test-results/junit.xml' }], ['html', { open: 'never' }]],
  use: {
    baseURL: process.env.BASE_URL || 'http://localhost:8080',
    viewport,
    reducedMotion: 'reduce',
    timezoneId: 'UTC',
    locale: 'en-US',
    trace: 'retain-on-failure',
    screenshot: 'only-on-failure',
  },
  // Start SplitPal (test hooks on) when the target is local. Remote BASE_URLs (Cloud Run tags) skip this.
  webServer: /localhost|127\.0\.0\.1/.test(process.env.BASE_URL || 'http://localhost:8080')
    ? {
        command: 'npm --prefix apps/carerx run start:test',
        url: 'http://localhost:8080/healthz',
        reuseExistingServer: true,
        timeout: 120_000,
        stdout: 'ignore',
        stderr: 'pipe',
      }
    : undefined,
  projects: [
    {
      name: 'chromium',
      use: { ...devices['Desktop Chrome'], viewport, reducedMotion: 'reduce', timezoneId: 'UTC' },
    },
  ],
});
